import json, glob, os
d = os.path.dirname(os.path.abspath(__file__))
total = 0
for f in sorted(glob.glob(os.path.join(d, "f*.json"))):
    try:
        j = json.load(open(f))
    except Exception:
        continue
    t = j.get("trail") or {}
    fs = j.get("findings") or []
    print(f"##### {os.path.basename(f)} trail#{t.get('number')} branch={t.get('branch')} base={t.get('base')} status={t.get('status')} n={len(fs)}")
    for x in fs:
        total += 1
        loc = x.get("location") or {}
        print(f"- [{x['severity']}/{x['status']}/{x.get('staleOutcome')}] {loc.get('filePath')}:{loc.get('startLine')}")
        print("  ", x["body"].replace("\n", " "))
        if x.get("statusReason"):
            print("   reason:", x["statusReason"])
print("TOTAL", total)

