1	//! Generic components, read through an instantiation the checker forms itself.
2	//!
3	//! The props parameter of `function Poly<E extends ElementType = "div">(props: PolyProps<E>)` is `PolyProps<E>` with `E`
4	//! open, which has two props where `<Poly />` has every attribute of a `div`. The checker's API has no request that
5	//! instantiates a signature, so the instantiation is written as source: one file, held in the checker's memory and never
6	//! on disk (`createSnapshot` with a `fileSystem` layer), declares for each such component
7	//!
8	//! ```ts
9	//! import type { "Poly" as CaliperComponent0 } from "/project/src/Poly.tsx"; export type CaliperProbe0 = Parameters<typeof CaliperComponent0<"div">>[0];
10	//! ```
11	//!
12	//! and the props are those of `CaliperProbe0`, read as any props type is. The file is added to a second snapshot of the
13	//! same program, made only when a requested component is generic, so a project without one sends no request more. A
14	//! line the checker reports an error on (a default it prints with a name the file cannot see) sends that component to
15	//! its structural result with the error as the reason, and a checker that does not load the file sends them all; a
16	//! result is never read from an instantiation that did not form.
17	
18	use std::sync::Arc;
19	
20	use caliper_docgen_core::types::semantic::{PropInterner, SemanticComponent, SemanticOutcome, SemanticProp};
21	use camino::Utf8Path;
22	use rustc_hash::FxHashMap;
23	
24	use crate::component;
25	use crate::convert::Converter;
26	use crate::rpc::{CallError, Rpc, SignatureInfo};
27	use crate::{Target, fallback_of};
28	
29	/// The file the instantiations are declared in, in the project's root directory. It exists only in the checker's memory.
30	const PROBE_FILE: &str = "__caliper_instantiations__.ts";
31	
32	/// A generic component to read through an instantiation: the name its module exports it under, and the type arguments.
33	#[derive(Debug, Clone)]
34	pub(crate) struct Instantiation {
35	    pub export: String,
36	    pub arguments: Vec<String>,
37	}
38	
39	/// The type arguments of the instantiation a generic component gets when written without any (`<Poly />`): its first
40	/// type parameter's declared default, as the checker prints it. The checker fills in the parameters after it from their
41	/// own defaults, which may refer to the first. `None` when the component is not generic or its first type parameter
42	/// declares no default: then no instantiation is the one a story renders, and the props keep the open parameters.
43	pub(crate) async fn default_arguments(rpc: &Rpc, signature: &SignatureInfo) -> Result<Option<Vec<String>>, CallError> {
44	    if signature.type_parameters.is_empty() {
45	        return Ok(None);
46	    }
47	    // The ids a signature lists are not handles the checker knows until it has answered for them itself.
48	    let parameters = rpc.type_parameters(signature.id).await?;
49	    let Some(first) = parameters.first() else { return Ok(None) };
50	    let Some(default) = rpc.default_of_type_parameter(first.id).await? else { return Ok(None) };
51	    Ok(Some(vec![rpc.type_to_string(default.id).await?]))
52	}
53	
54	/// The line of the probe file that instantiates `instantiation`, the component exported by `file`. Each component is one
55	/// line, so an error the checker reports is the error of the line it starts on.
56	fn probe_line(index: usize, file: &Utf8Path, instantiation: &Instantiation) -> String {
57	    let quoted = |text: &str| serde_json::Value::String(text.to_string()).to_string();
58	    format!(
59	        "import type {{ {export} as CaliperComponent{index} }} from {file}; export type CaliperProbe{index} = \
60	         Parameters<typeof CaliperComponent{index}<{arguments}>>[0];",
61	        export = quoted(&instantiation.export),
62	        file = quoted(file.as_str()),
63	        arguments = instantiation.arguments.join(", "),
64	    )
65	}
66	
67	/// The written form of an instantiation, for a reason: `Poly<"div">`.
68	fn written(target: &Target, instantiation: &Instantiation) -> String {
69	    format!("{}<{}>", target.display_name, instantiation.arguments.join(", "))
70	}
71	
72	/// Answers each generic component from its instantiation, in a snapshot of `rpc`'s program over `root_files` with the
73	/// probe file added. The snapshot is released before this returns.
74	pub(crate) async fn answer(
75	    rpc: &Rpc,
76	    root_files: &[String],
77	    project_root: &Utf8Path,
78	    interner: &PropInterner,
79	    reverse: bool,
80	    mut pending: Vec<(Target, Instantiation)>,
81	) -> Result<SemanticOutcome, CallError> {
82	    let mut outcome = SemanticOutcome::default();
83	    // The file's text is part of the request, so it must not depend on the order the components were answered in.
84	    pending.sort_by(|(a, _), (b, _)| (&a.file_path, &a.display_name).cmp(&(&b.file_path, &b.display_name)));
85	    let probe = project_root.join(PROBE_FILE);
86	    let text: Vec<String> = pending
87	        .iter()
88	        .enumerate()
89	        .map(|(index, (target, instantiation))| probe_line(index, &target.file_path, instantiation))
90	        .collect();
91	    let all_fall_back = |outcome: &mut SemanticOutcome, reason: &str| {
92	        outcome.fallbacks.extend(pending.iter().map(|(target, _)| fallback_of(target, reason)));
93	    };
94	
95	    let layered = match rpc.layered(root_files, &[(probe.to_string(), text.join("\n"))]).await {
96	        Ok(layered) => Arc::new(layered),
97	        Err(CallError::Rejected(message)) => {
98	            all_fall_back(&mut outcome, &format!("the checker could not instantiate a generic component: {message}"));
99	            return Ok(outcome);
100	        }
101	        Err(fatal) => return Err(fatal),
102	    };
103	    let answered = answer_layered(&layered, probe.as_str(), interner, reverse, &pending).await;
104	    layered.release().await;
105	    match answered {
106	        Ok(answered) => Ok(answered),
107	        Err(CallError::Rejected(message)) => {
108	            all_fall_back(&mut outcome, &format!("the checker rejected a request: {message}"));
109	            Ok(outcome)
110	        }
111	        Err(fatal) => Err(fatal),
112	    }
113	}
114	
115	async fn answer_layered(
116	    layered: &Arc<Rpc>,
117	    probe: &str,
118	    interner: &PropInterner,
119	    reverse: bool,
120	    pending: &[(Target, Instantiation)],
121	) -> Result<SemanticOutcome, CallError> {
122	    let mut outcome = SemanticOutcome::default();
123	    let Some(module) = layered.source_file_symbol(probe).await? else {
124	        let reason = "the checker did not load the file that instantiates generic components";
125	        outcome.fallbacks.extend(pending.iter().map(|(target, _)| fallback_of(target, reason)));
126	        return Ok(outcome);
127	    };
128	    let probes: FxHashMap<String, serde_json::Value> = layered
129	        .exports_of_module(&module.reference)
130	        .await?
131	        .into_iter()
132	        .map(|symbol| (symbol.name, symbol.reference))
133	        .collect();
134	    let mut errors: FxHashMap<usize, String> = FxHashMap::default();
135	    for diagnostic in layered.semantic_diagnostics(probe).await?.into_iter().filter(|d| d.is_error()) {
136	        errors.entry(diagnostic.start_position.line).or_insert_with(|| diagnostic.message());
137	    }
138	
139	    let converter = Converter::new(layered.clone(), reverse);
140	    for (index, (target, instantiation)) in pending.iter().enumerate() {
141	        let read = match (errors.get(&index), probes.get(&format!("CaliperProbe{index}"))) {
142	            (Some(error), _) => {
143	                Err(format!("the instantiation {} could not be formed: {error}", written(target, instantiation)))
144	            }
145	            (None, None) => Err(format!("the instantiation {} was not declared", written(target, instantiation))),
146	            (None, Some(symbol)) => match read_probe(layered, &converter, interner, symbol, target).await {
147	                Ok(read) => read,
148	                Err(CallError::Rejected(message)) => Err(format!("the checker rejected a request: {message}")),
149	                Err(fatal) => return Err(fatal),
150	            },
151	        };
152	        match read {
153	            Ok(props) => outcome.components.push(SemanticComponent {
154	                file_path: target.file_path.clone(),
155	                display_name: target.display_name.clone(),
156	                props,
157	            }),
158	            Err(reason) => outcome.fallbacks.push(fallback_of(target, &reason)),
159	        }
160	    }
161	    Ok(outcome)
162	}
163	
164	async fn read_probe(
165	    layered: &Rpc,
166	    converter: &Converter,
167	    interner: &PropInterner,
168	    symbol: &serde_json::Value,
169	    target: &Target,
170	) -> Result<Result<Vec<Arc<SemanticProp>>, String>, CallError> {
171	    let props_type = layered.declared_type_of_symbol(symbol).await?;
172	    component::props_of_type(layered, converter, interner, &props_type, target).await
173	}
174	
175	#[cfg(test)]
176	mod tests {
177	    use super::*;
178	
179	    #[test]
180	    fn a_probe_line_imports_the_export_by_its_quoted_name_and_instantiates_it() {
181	        let instantiation = Instantiation { export: "default".to_string(), arguments: vec!["\"div\"".to_string()] };
182	
183	        let line = probe_line(3, Utf8Path::new("/p/src/Poly.tsx"), &instantiation);
