214	    /// ADR 0026's S5 gate: `Poly<"div">` has at least 260 props, and `Poly<"a">` others.
215	    #[test]
216	    #[allow(clippy::unwrap_used, clippy::expect_used, clippy::print_stderr)]
217	    fn a_polymorphic_component_has_the_props_of_the_element_it_is_instantiated_with() {
218	        let Some(checker) = real_checker() else { return };
219	        let root = camino::Utf8PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/generic");
220	        let file = root.join("Poly.tsx");
