231	        request.tsc_path = Some(checker);
232	        let config = crate::supervisor_config(&request).unwrap();
233	        let timeout = std::time::Duration::from_secs(60);
234	        let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap();
235	
236	        let outcome = runtime.block_on(async {
237	            let supervisor = caliper_docgen_tsc_client::Supervisor::spawn(config).await.unwrap();
238	            let tsconfig = root.join("tsconfig.json");
239	            let files = [file.to_string()];
240	            let rpc = Rpc::open(supervisor.client(), timeout, Some(tsconfig.as_str()), &files, false).await.unwrap();
241	            let pending = vec![(target("Poly<div>"), at("div")), (target("Poly<a>"), at("a"))];
242	            let outcome = answer(&rpc, &files, &root, &PropInterner::default(), false, pending).await.unwrap();
243	            rpc.release().await;
